const documentShell = ({ title, styles, body, script }) => {
  const brandedTitle = title.replaceAll("TUMA", "L’Horloger");
  const brandedBody = body.replaceAll("TUMA", "L’Horloger").replaceAll("L’Horloger-REV", "HOR-REV");
  return `<!doctype html>
<html lang="fr">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="Version de revue locale L’Horloger">
  <title>${brandedTitle}</title>
  <style>${styles}
  @media(max-width:760px) { .variant-list{grid-template-columns:repeat(auto-fit,minmax(min(132px,100%),1fr))}.variant{grid-template-columns:38px 12px minmax(0,1fr);gap:7px;min-height:40px}.variant img{width:38px;height:40px}.variant i{width:12px;height:12px} }
  </style>
</head>
<body>${brandedBody}<script>${script}</script></body>
</html>`;
};

