const storeBody = `<div class="notice">L’Horloger · version de revue locale — données de démonstration</div><header class="nav"><button class="brand" data-go="home">L’Horloger</button><nav class="nav-links"><button data-go="catalog">Catalogue</button><button data-go="cart">Panier <span class="cart-count" id="cart-count">0</span></button></nav></header><main class="page" id="app"></main><footer>Le temps vous va si bien.</footer>`;

let storeScript = `
const products = ${JSON.stringify(products)};
let cart = []; let route = 'home'; let current = products[0]; let filter = 'Tous'; let galleryIndex = 0; let variantId = current.variants[0].id;
const money = value => new Intl.NumberFormat('fr-FR').format(value) + ' FCFA';
const app = document.getElementById('app');
const escape = value => String(value).replace(/[&<>\"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char]));
function card(product) { return '<article class="card"><button class="card-image-button" type="button" data-product="'+product.id+'" aria-label="Voir '+escape(product.name)+'"><img src="'+product.image+'" alt="'+escape(product.name)+'"></button><div class="card-copy"><p class="card-reference">Sélection L’Horloger · '+product.reference+'</p><div class="card-title"><h3>'+product.name+'</h3><strong>'+money(product.price)+'</strong></div><p>'+product.description+'</p><div class="card-actions"><button class="text-button" data-product="'+product.id+'">Voir le modèle</button><button class="add" data-add="'+product.id+'">Ajouter</button></div></div></article>'; }
function nav() { document.querySelectorAll('[data-go]').forEach(button => button.onclick = () => { route = button.dataset.go; render(); window.scrollTo(0,0); }); document.querySelectorAll('[data-product]').forEach(button => button.onclick = () => { current = products.find(product => product.id === button.dataset.product); galleryIndex=0; variantId=current.variants[0].id; route='product'; render(); window.scrollTo(0,0); }); document.querySelectorAll('[data-add]').forEach(button => button.onclick = () => { add(button.dataset.add); button.textContent='Ajouté'; setTimeout(() => button.textContent='Ajouter',900); }); document.getElementById('cart-count').textContent = cart.reduce((sum,line) => sum+line.quantity,0); }
function add(id, quantity=1, variant) { const item=products.find(product => product.id===id), resolvedVariant=variant||item.variants[0].label, key=id+':'+resolvedVariant; const line = cart.find(item => item.key === key); if (line) line.quantity += quantity; else cart.push({id,key,quantity,variant:resolvedVariant}); document.getElementById('cart-count').textContent = cart.reduce((sum,item) => sum+item.quantity,0); }
function home() { return '<section class="hero"><div class="hero-copy"><p class="eyebrow">Sélection de montres · Bamako</p><h1>Une montre qui finit la tenue.</h1><p>Trois modèles aux lignes affirmées, pensés pour se porter souvent. Choisissez votre montre, nous confirmons le quartier, puis vous réglez à la réception.</p><p><button class="button light" data-go="catalog">Voir la sélection</button></p></div><img class="hero-image" src="'+products[0].image+'" alt="Nocturne Chrono portée au poignet"></section><section class="proofs"><div><strong>0 FCFA</strong><span>de frais de livraison</span></div><div><strong>À la réception</strong><span>vous réglez votre commande</span></div><div><strong>À Bamako</strong><span>livraison sur rendez-vous</span></div></section><section class="section container"><div class="section-head"><div><p class="eyebrow">La sélection L’Horloger</p><h2>Les modèles du moment</h2></div><p>Une sélection courte, avec les détails utiles pour choisir sans hésiter.</p></div><div class="grid">'+products.map(card).join('')+'</div></section>'; }
function catalog() { const displayed = filter === 'Tous' ? products : products.filter(product => product.bracelet.includes(filter)); return '<section class="catalog container"><p class="eyebrow">Toutes les montres</p><div class="catalog-head"><h1>Le temps, à votre mesure.</h1><div class="filter">'+['Tous','Cuir','Acier'].map(value => '<button class="'+(filter===value?'active':'')+'" data-filter="'+value+'">'+value+'</button>').join('')+'</div></div><div class="grid">'+displayed.map(card).join('')+'</div></section>'; }
function legacyProduct() { return '<section class="product container"><img class="product-image" src="'+current.image+'" alt="'+escape(current.name)+'"><div class="product-info"><p class="eyebrow">Sélection TUMA · '+current.reference+'</p><h1>'+current.name+'</h1><p class="product-price">'+money(current.price)+'</p><p class="product-description">'+current.description+'</p><div class="specs"><span><b>Bracelet</b>'+current.bracelet+'</span><span><b>Finition</b>'+current.finish+'</span><span><b>Diamètre</b>'+current.size+'</span></div><div class="purchase"><div class="quantity"><button id="minus">−</button><span id="quantity">1</span><button id="plus">+</button></div><button class="button" id="order">Commander maintenant</button></div><div class="reassurance"><span>Livraison offerte à Bamako</span><span>Paiement à la réception</span></div></div></section>'; }
function cartView() { const lines = cart.map(line => ({...line, product:products.find(product => product.id===line.id)})); const total = lines.reduce((sum,line)=>sum+line.quantity*line.product.price,0); return '<section class="cart container"><div><p class="eyebrow">Votre sélection</p><h1>Panier</h1>'+(lines.length?'<div class="lines">'+lines.map(line=>'<article class="line"><img src="'+line.product.image+'" alt=""><div><p>Sélection TUMA · '+line.product.reference+'</p><h3>'+line.product.name+'</h3><p>'+line.variant+' · '+line.quantity+' × '+money(line.product.price)+'</p></div><strong>'+money(line.quantity*line.product.price)+'</strong></article>').join('')+'</div>':'<div class="empty"><p>Votre panier est vide.</p><button class="button" data-go="catalog">Voir les montres</button></div>')+'</div>'+(lines.length?'<aside class="summary"><h2>Récapitulatif</h2><div><span>Sous-total</span><strong>'+money(total)+'</strong></div><div><span>Livraison</span><strong>Offerte</strong></div><div><span>Total</span><strong>'+money(total)+'</strong></div><button class="button" data-go="checkout">Passer à la commande</button></aside>':'')+'</section>'; }
function checkout() { const lines=cart.map(line=>({...line,product:products.find(product=>product.id===line.id)})),total=lines.reduce((sum,line)=>sum+line.quantity*line.product.price,0); return '<section class="checkout container"><div><p class="eyebrow">Finaliser votre commande</p><h1>Vos informations de livraison</h1><p class="product-description">Nous vous contacterons avant toute livraison.</p><form class="form" id="checkout-form"><div class="form-grid"><label>Prénom<input required name="firstName"></label><label>Nom<input required name="lastName"></label></div><div class="form-grid"><label>Téléphone<input required name="phone" placeholder="+223 XX XX XX XX"></label><label>Quartier<input required name="district"></label></div><button class="button">Confirmer ma commande</button></form></div><aside class="summary"><h2>Votre commande</h2>'+lines.map(line=>'<div><span>'+line.product.name+' · '+line.variant+' × '+line.quantity+'</span><strong>'+money(line.product.price*line.quantity)+'</strong></div>').join('')+'<div><span>Livraison</span><strong>Offerte</strong></div><div><span>Total</span><strong>'+money(total)+'</strong></div></aside></section>'; }
function success(name) { return '<section class="success"><p class="eyebrow">Commande enregistrée</p><h1>Merci, '+escape(name||'client')+'.</h1><p>Votre demande de commande a bien été enregistrée. L’équipe TUMA vous contactera pour confirmer le quartier et le créneau de livraison.</p><strong>Référence TUMA-REV-'+Math.floor(100000+Math.random()*900000)+'</strong><p style="margin-top:28px"><button class="button" data-go="catalog">Retour aux montres</button></p></section>'; }
function render() { if(route==='home') app.innerHTML=home(); if(route==='catalog') app.innerHTML=catalog(); if(route==='product') app.innerHTML=product(); if(route==='cart') app.innerHTML=cartView(); if(route==='checkout') app.innerHTML=checkout(); nav(); document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{filter=button.dataset.filter;render();}); const order=document.getElementById('order'); if(order){let quantity=1;document.getElementById('minus').onclick=()=>{quantity=Math.max(1,quantity-1);document.getElementById('quantity').textContent=quantity};document.getElementById('plus').onclick=()=>{quantity++;document.getElementById('quantity').textContent=quantity};order.onclick=()=>{add(current.id,quantity);route='checkout';render();window.scrollTo(0,0)}} const form=document.getElementById('checkout-form'); if(form) form.onsubmit=event=>{event.preventDefault();const formData=new FormData(form);cart=[];app.innerHTML=success(formData.get('firstName'));nav();window.scrollTo(0,0)}; }
function product() {
  const selected = current.variants.find(variant => variant.id === variantId) || current.variants[0];
  const selectionGallery = [selected.image].concat(current.gallery.filter(image => image.src !== selected.image.src));
  const active = selectionGallery[galleryIndex];
  const gallery = selectionGallery.map((image, index) => '<button class="gallery-thumb '+(galleryIndex===index?'active':'')+'" data-gallery="'+index+'"><img src="'+image.src+'" alt=""><span>'+image.label+'</span></button>').join('');
  const technical = current.specifications.map(specification => '<div><dt>'+specification[0]+'</dt><dd>'+specification[1]+'</dd></div>').join('');
  const features = current.features.map((feature,index) => '<article><span>0'+(index+1)+'</span><h3>'+feature.title+'</h3><p>'+feature.copy+'</p></article>').join('');
  const variants = current.variants.length > 1 ? '<section class="variants"><div class="variants-head"><b>Choisir le coloris</b><span>'+selected.description+'</span></div><div class="variant-list">'+current.variants.map(variant => '<button class="variant '+(variant.id===selected.id?'active':'')+'" data-variant="'+variant.id+'"><img src="'+variant.image.src+'" alt=""><i style="background:'+variant.swatch+'"></i><span>'+variant.label+'</span></button>').join('')+'</div></section>' : '';
  const benefits = current.benefits.map(benefit => '<article><strong>'+benefit.mark+'</strong><div><span>'+benefit.label+'</span><h3>'+benefit.value+'</h3><p>'+benefit.copy+'</p></div></article>').join('');
  return '<section class="product container"><div class="product-gallery"><img class="product-image" src="'+active.src+'" alt="'+escape(current.name)+' — '+escape(active.label)+'"><p class="gallery-caption"><span>'+active.caption+'</span><span>'+(galleryIndex+1)+' / '+selectionGallery.length+'</span></p><div class="gallery-thumbs">'+gallery+'</div></div><div class="product-info"><p class="eyebrow">Sélection TUMA · '+current.reference+'</p><h1>'+current.name+'</h1><p class="product-price">'+money(current.price)+'</p><p class="product-description">'+current.description+'</p><div class="product-story"><p class="eyebrow">L’esprit du modèle</p><h2>'+current.storyTitle+'</h2><p>'+current.styleNote+'</p></div><div class="specs"><span><b>Coloris</b>'+selected.label+'</span><span><b>Finition</b>'+current.finish+'</span><span><b>Diamètre</b>'+current.size+'</span></div>'+variants+'<div class="purchase"><div class="quantity"><button id="minus">−</button><span id="quantity">1</span><button id="plus">+</button></div><button class="button" id="order">Commander maintenant</button></div><div class="reassurance"><span>Livraison offerte à Bamako</span><span>Paiement à la réception</span></div><details class="technical" open><summary>Fiche technique</summary><p>Les dimensions et fonctions sont renseignées selon la fiche du modèle ; les finitions complètent sa description visuelle.</p><dl>'+technical+'</dl></details></div></section><section class="product-editorial container"><img src="'+current.editorial.image+'" alt=""><div class="product-editorial__copy"><p class="eyebrow">'+current.editorial.eyebrow+'</p><h2>'+current.editorial.title+'</h2><p>'+current.editorial.copy+'</p></div></section><section class="benefits container"><div class="benefits-intro"><p class="eyebrow">Repères essentiels</p><h2>Les fonctions en un regard.</h2></div><div class="benefit-grid">'+benefits+'</div></section><section class="feature-section container"><div class="feature-section__head"><p class="eyebrow">Les détails qui comptent</p><h2>Une montre pensée pour être portée.</h2></div><div class="feature-grid">'+features+'</div></section>';
}
document.addEventListener('click', event => { const button = event.target.closest('[data-gallery]'); if (button) { galleryIndex = Number(button.dataset.gallery); render(); } });
document.addEventListener('click', event => { const button = event.target.closest('[data-variant]'); if (button) { variantId = button.dataset.variant; galleryIndex = 0; render(); } });
render();
`;

storeScript = storeScript.replaceAll("TUMA", "L’Horloger").replaceAll("L’Horloger-REV-", "HOR-REV-");

const adminStyles = `
  :root { --ink:#1b1a18; --paper:#f4f2ed; --panel:#fbfaf7; --line:#dedbd4; --gold:#a77c3c; --muted:#756f66; --green:#557044; } *{box-sizing:border-box} body{margin:0;background:var(--paper);color:var(--ink);font-family:Arial,Helvetica,sans-serif} button,input,select{font:inherit}button{cursor:pointer}.review{padding:8px 18px;background:#1b1a18;color:#f9f6ee;text-align:center;font-size:10px;font-weight:800;letter-spacing:.09em;text-transform:uppercase}.shell{display:grid;grid-template-columns:255px minmax(0,1fr);min-height:100vh}.side{display:grid;align-content:start;gap:30px;padding:27px 18px;background:#1b1a18;color:#f8f6ef}.logo{font-family:Georgia,serif;font-size:33px;letter-spacing:.14em}.side p{margin:0;color:#b8afa3;font-size:10px;letter-spacing:.1em;text-transform:uppercase}.side nav{display:grid;gap:5px}.side nav button{border:0;padding:13px 12px;background:transparent;color:#c3bcb1;text-align:left;font-size:12px;font-weight:700}.side nav button.active{background:#33312c;color:#fff}.side small{margin-top:40px;color:#9b9387;font-size:10px;line-height:1.5}.main{min-width:0}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:20px clamp(20px,4vw,48px);border-bottom:1px solid var(--line);background:var(--panel)}.top p{margin:0;color:var(--muted);font-size:12px}.top button{border:1px solid var(--ink);padding:9px 11px;background:var(--ink);color:#fff;font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase}.content{padding:45px clamp(20px,4vw,48px) 60px}.head{display:flex;align-items:flex-end;justify-content:space-between;gap:25px;margin-bottom:28px}.kicker{margin:0 0 9px;color:#98733d;font-size:10px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.head h1{margin:0;font-family:Georgia,serif;font-size:clamp(42px,5vw,66px);font-weight:500;letter-spacing:-.05em}.period{display:grid;gap:5px;min-width:200px}.period span,.field span{color:var(--muted);font-size:9px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.period select,.field select,.field input{min-height:40px;border:1px solid #d3d0c8;padding:8px 10px;background:#fffefa;color:var(--ink);font-size:12px}.range{display:flex;gap:8px;margin:0 0 18px}.range label{display:grid;gap:4px;color:var(--muted);font-size:9px;font-weight:800;text-transform:uppercase}.range input{border:1px solid #d3d0c8;padding:8px;background:#fffefa}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:16px}.metric{display:grid;gap:14px;min-width:0;padding:21px;background:var(--panel)}.metric p{margin:0;color:var(--muted);font-size:10px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.metric strong{overflow:hidden;font-family:Georgia,serif;font-size:27px;font-weight:500;letter-spacing:-.04em;text-overflow:ellipsis;white-space:nowrap}.metric span{color:var(--green);font-size:11px;font-weight:700}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.panel{min-width:0;padding:24px;background:var(--panel)}.panel h2{margin:0;font-family:Georgia,serif;font-size:34px;font-weight:500;letter-spacing:-.04em}.panel-head{display:flex;align-items:start;justify-content:space-between;gap:14px;margin-bottom:23px}.panel-head button{border:0;border-bottom:1px solid #786f63;padding:0;background:transparent;color:#514b43;font-size:10px;font-weight:800;letter-spacing:.05em;text-transform:uppercase}.bars{display:grid;grid-template-columns:repeat(7,1fr);align-items:end;gap:10px;height:190px;border-bottom:1px solid var(--line)}.bar{display:grid;align-items:end;height:100%;background:linear-gradient(to top,#b28d55 var(--h),transparent var(--h))}.bar span{margin-bottom:-24px;color:var(--muted);font-size:9px;text-align:center}.orders{display:grid}.order{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:13px;padding:16px 0;border-top:1px solid var(--line)}.order strong{font-size:13px}.order p{margin:4px 0 0;color:var(--muted);font-size:11px}.chip{width:max-content;height:max-content;padding:5px 7px;background:#e9ede5;color:var(--green);font-size:8px;font-weight:800;letter-spacing:.06em;text-transform:uppercase}.table{border-top:1px solid var(--line)}.table-row{display:grid;grid-template-columns:minmax(140px,1.5fr) repeat(4,minmax(72px,.7fr));gap:12px;align-items:center;padding:15px 0;border-bottom:1px solid var(--line);font-size:12px}.table-row.head-row{color:var(--muted);font-size:9px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.table-row strong{font-family:Georgia,serif;font-size:19px;font-weight:500}.stock-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.stock-card{display:grid;gap:13px;min-width:0;border:1px solid var(--line);padding:18px;background:var(--panel);text-align:left}.stock-card:hover,.stock-card.active{border-color:#967033}.stock-card p{margin:0;color:#967033;font-size:9px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.stock-card h3{margin:0;font-family:Georgia,serif;font-size:27px;font-weight:500}.stock-card strong{font-family:Georgia,serif;font-size:35px;font-weight:500}.stock-card span{color:var(--muted);font-size:11px}.detail{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:16px;padding:24px;background:var(--panel)}.detail h2{margin:0;font-family:Georgia,serif;font-size:34px;font-weight:500}.costs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;background:var(--line)}.costs span{display:grid;gap:6px;padding:13px;background:#f2f0eb;color:var(--muted);font-size:9px;font-weight:800;letter-spacing:.06em;text-transform:uppercase}.costs b{color:var(--ink);font-size:13px;letter-spacing:0;text-transform:none}.form{display:grid;grid-template-columns:1fr 1fr;gap:11px}.field{display:grid;gap:5px}.form button{grid-column:1/-1;border:0;padding:12px;background:var(--ink);color:#fff;font-size:10px;font-weight:800;letter-spacing:.07em;text-transform:uppercase}.cac{grid-column:1/-1;margin:0;padding:12px;border-left:3px solid var(--gold);background:#f1ede4;color:#504a43;font-size:12px;line-height:1.5}.events{grid-column:1/-1;border-top:1px solid var(--line)}.event{display:flex;justify-content:space-between;gap:14px;padding:13px 0;border-bottom:1px solid var(--line);font-size:12px}.event small{color:var(--muted)}.toast{position:fixed;right:20px;top:20px;z-index:3;padding:15px 18px;background:#1b1a18;color:#fff;box-shadow:0 14px 35px rgba(0,0,0,.2);font-size:12px}.hidden{display:none}@media(max-width:980px){.shell{display:block}.side{display:flex;align-items:center;gap:16px;padding:15px 20px}.side nav{display:flex;overflow:auto}.side nav button{white-space:nowrap}.side small{display:none}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.stock-grid{grid-template-columns:1fr 1fr}}@media(max-width:640px){.top{padding:15px 20px}.top p{display:none}.content{padding:34px 20px}.head{align-items:start;flex-direction:column}.period{width:100%}.period select{width:100%}.range{width:100%}.range label{width:50%}.range input{width:100%}.metrics,.grid,.stock-grid,.detail{grid-template-columns:1fr}.metric strong{font-size:25px}.panel{padding:19px}.table{overflow:auto}.table-row{min-width:600px}.form{grid-template-columns:1fr}.detail{padding:19px}.side .logo{font-size:25px}.side{padding:13px 15px}.stock-card h3{font-size:25px}}
`;

const adminBody = `<div class="review">TUMA · version de revue locale — administration</div><div class="shell"><aside class="side"><div><div class="logo">TUMA</div><p>Gestion locale</p></div><nav><button data-page="overview" class="active">Vue d’ensemble</button><button data-page="orders">Commandes</button><button data-page="stock">Stock & coûts</button><button data-page="analysis">Analyse produits</button></nav><small>Données de démonstration. Cette version autonome ne synchronise aucune commande réelle.</small></aside><main class="main"><header class="top"><p>Administration TUMA · Bamako</p><button id="notify">Tester l’alerte</button></header><div class="content" id="admin-app"></div></main></div><div class="toast hidden" id="toast">✦ Nouvelle commande reçue<br><small>TUMA-REV-483922 · Azur Squelette</small></div>`;

const adminScript = `
const products = ${JSON.stringify(products.map(({ image, description, gallery, variants, benefits, storyTitle, styleNote, specifications, features, editorial, ...product }) => product))};
const periods={today:'Aujourd’hui',yesterday:'Hier','7':'7 derniers jours','14':'14 derniers jours','30':'30 derniers jours',quarter:'Ce trimestre','90':'90 derniers jours',year:'Depuis le 1er janvier',custom:'Période personnalisée'};let page='overview',period='7',selected=null,adSpend=0,adPeriod='30';const app=document.getElementById('admin-app');const money=value=>new Intl.NumberFormat('fr-FR').format(Math.round(value))+' FCFA';const mult={today:.18,yesterday:.16,'7':1,'14':1.85,'30':3.8,quarter:9.2,'90':10.6,year:38.6,custom:2.7};const base=[{id:'tuma-01',units:13,revenue:676000,margin:279500,stock:18,cost:30500},{id:'tuma-02',units:10,revenue:620000,margin:234000,stock:8,cost:38600},{id:'tuma-03',units:9,revenue:531000,margin:205200,stock:4,cost:36200}];function product(id){return products.find(item=>item.id===id)}function scale(value){return Math.round(value*(mult[period]||1))}function header(title,kicker){return '<section class="head"><div><p class="kicker">'+kicker+'</p><h1>'+title+'</h1></div><label class="period"><span>Période analysée</span><select id="period">'+Object.entries(periods).map(entry=>'<option value="'+entry[0]+'" '+(entry[0]===period?'selected':'')+'>'+entry[1]+'</option>').join('')+'</select></label></section>'+(period==='custom'?'<div class="range"><label>Du<input type="date" value="2026-08-01"></label><label>Au<input type="date" value="2026-08-19"></label></div>':'')}function overview(){const revenue=base.reduce((sum,item)=>sum+scale(item.revenue),0),margin=base.reduce((sum,item)=>sum+scale(item.margin),0),orders=base.reduce((sum,item)=>sum+scale(item.units),0);return header('Les repères pour décider.','Vue d’ensemble')+'<section class="metrics"><article class="metric"><p>Chiffre d’affaires</p><strong>'+money(revenue)+'</strong><span>'+periods[period]+'</span></article><article class="metric"><p>Marge brute</p><strong>'+money(margin)+'</strong><span>'+Math.round(margin/revenue*100)+' % de marge</span></article><article class="metric"><p>CAC Meta</p><strong>'+money(12900)+'</strong><span>Coût renseigné</span></article><article class="metric"><p>Commandes</p><strong>'+orders+'</strong><span>Toutes sources</span></article></section><section class="grid"><article class="panel"><div class="panel-head"><div><p class="kicker">Ventes</p><h2>Le rythme des ventes</h2></div></div><div class="bars">'+[38,56,46,78,64,92,72].map((value,index)=>'<div class="bar" style="--h:'+value+'%"><span>'+['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'][index]+'</span></div>').join('')+'</div></article><article class="panel"><div class="panel-head"><div><p class="kicker">À traiter</p><h2>Commandes récentes</h2></div><button data-page="orders">Tout voir</button></div>'+['Mahamadou K. Diarra|Azur Squelette|À confirmer','Aïssata Traoré|Éclipse Lunaire|Confirmée','Boubacar Koné|Nocturne Chrono|En livraison'].map(row=>{const [name,watch,status]=row.split('|');return '<div class="order"><div><strong>'+name+'</strong><p>'+watch+'</p></div><span class="chip">'+status+'</span></div>'}).join('')+'</article></section>'}function orders(){return header('Chaque détail à portée de main.','Commandes')+'<section class="panel"><div class="panel-head"><div><p class="kicker">Commandes</p><h2>Suivi des commandes</h2></div></div><div class="table"><div class="table-row head-row"><span>Client</span><span>Produit</span><span>Canal</span><span>Statut</span><span>Montant</span></div>'+[['Mahamadou K. Diarra','Azur Squelette','À renseigner','À confirmer','62 000 FCFA'],['Aïssata Traoré','Éclipse Lunaire','Réachat','Confirmée','59 000 FCFA'],['Boubacar Koné','Nocturne Chrono','Meta','En livraison','104 000 FCFA']].map(row=>'<div class="table-row"><strong>'+row[0]+'</strong><span>'+row[1]+'</span><span>'+row[2]+'</span><span class="chip">'+row[3]+'</span><strong>'+row[4]+'</strong></div>').join('')+'</div></section>'}function stock(){return header('Garder la bonne mesure.','Stock & coûts')+'<section class="stock-grid">'+base.map(item=>{const watch=product(item.id),margin=watch.price-item.cost;return '<button class="stock-card '+(selected===item.id?'active':'')+'" data-stock="'+item.id+'"><p>'+watch.reference+' · Publicité & CAC</p><h3>'+watch.name+'</h3><strong>'+item.stock+' unités</strong><span>Coût unitaire '+money(item.cost)+'</span><span>Marge / unité '+money(margin)+'</span><span>'+ (selected===item.id&&adSpend?'CAC '+money(adSpend/(scale(item.units)||1)):'Renseigner les coûts d’ads')+'</span></button>'}).join('')+'</section>'+(selected?detail():'')}function detail(){const item=base.find(entry=>entry.id===selected),watch=product(selected),cac=adSpend?adSpend/(scale(item.units)||1):null;return '<section class="detail"><div><p class="kicker">Fiche produit</p><h2>'+watch.name+'</h2><p style="color:#756f66;font-size:12px;line-height:1.5">Les éléments du réassort déterminent automatiquement le coût unitaire moyen.</p><div class="costs"><span>Quantité<b>10 unités</b></span><span>Prix d’achat<b>'+money(item.cost*8)+'</b></span><span>Transit<b>'+money(item.cost*2)+'</b></span><span>Coût unitaire<b>'+money(item.cost)+'</b></span></div></div><form class="form" id="ad-form"><div class="field"><span>Période publicitaire</span><select id="ad-period"><option value="7">7 derniers jours</option><option value="30" selected>30 derniers jours</option><option value="90">90 derniers jours</option></select></div><div class="field"><span>Coût des ads</span><input id="ad-spend" type="number" min="0" placeholder="Ex. 75 000"></div><button>Enregistrer le coût</button><p class="cac">'+(cac?'CAC '+periods[adPeriod]+' : '+money(adSpend)+' de publicité / '+scale(item.units)+' ventes = '+money(cac):'Renseignez un coût publicitaire et sélectionnez une période pour calculer le CAC.')+'</p></form><div class="events"><p class="kicker" style="margin-top:16px">Historique</p><div class="event"><span>Réassort · 12 août 2026</span><strong>+10 unités</strong><small>Achat et transit renseignés</small></div><div class="event"><span>Sortie · aujourd’hui</span><strong>−1 unité</strong><small>Commande confirmée</small></div>'+(adSpend?'<div class="event"><span>Publicité · à l’instant</span><strong>'+money(adSpend)+'</strong><small>'+periods[adPeriod]+'</small></div>':'')+'</div></section>'}function analysis(){const rows=[...base].sort((a,b)=>b.margin-a.margin);return header('Voir ce qui est vraiment rentable.','Analyse produits')+'<section class="metrics"><article class="metric"><p>Meilleur CA</p><strong>Nocturne Chrono</strong><span>'+money(scale(676000))+'</span></article><article class="metric"><p>Meilleure marge</p><strong>Nocturne Chrono</strong><span>'+money(scale(279500))+'</span></article><article class="metric"><p>À sécuriser</p><strong>Éclipse Lunaire</strong><span>4 unités pour un seuil de 6</span></article><article class="metric"><p>Période</p><strong>'+periods[period]+'</strong><span>Filtre actif</span></article></section><section class="panel"><div class="panel-head"><div><p class="kicker">Classement détaillé</p><h2>Produits par rentabilité</h2></div></div><div class="table"><div class="table-row head-row"><span>Produit</span><span>Ventes</span><span>CA</span><span>Marge</span><span>Stock</span></div>'+rows.map(item=>{const watch=product(item.id);return '<div class="table-row"><strong>'+watch.name+'</strong><span>'+scale(item.units)+' unités</span><strong>'+money(scale(item.revenue))+'</strong><strong>'+money(scale(item.margin))+'</strong><span>'+item.stock+' unités</span></div>'}).join('')+'</div></section>'}function render(){app.innerHTML=page==='overview'?overview():page==='orders'?orders():page==='stock'?stock():analysis();document.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>{page=button.dataset.page;document.querySelectorAll('[data-page]').forEach(item=>item.classList.toggle('active',item.dataset.page===page));render()});const select=document.getElementById('period');if(select)select.onchange=event=>{period=event.target.value;render()};document.querySelectorAll('[data-stock]').forEach(button=>button.onclick=()=>{selected=button.dataset.stock;render()});const form=document.getElementById('ad-form');if(form)form.onsubmit=event=>{event.preventDefault();adSpend=Number(document.getElementById('ad-spend').value)||0;adPeriod=document.getElementById('ad-period').value;render()}}document.getElementById('notify').onclick=()=>{const toast=document.getElementById('toast');toast.classList.remove('hidden');setTimeout(()=>toast.classList.add('hidden'),3800)};render();
`;

const adminOrderDetailsScript = `
const orderConfigurations=[
  {id:'HOR-2608-483921',customer:'Mahamadou K. Diarra',phone:'+223 92 61 84 53',district:'Yirimadio',product:'Azur Squelette',reference:'T-02',color:'Bleu & or',finish:'Acier brossé',size:'42 mm',quantity:1,unit:62000,total:62000},
  {id:'HOR-2608-483920',customer:'Aïssata Traoré',phone:'+223 76 25 04 18',district:'Badalabougou',product:'Éclipse Lunaire',reference:'T-03',color:'Argent & brun',finish:'Acier poli',size:'40 mm',quantity:1,unit:59000,total:59000},
  {id:'HOR-2608-483917',customer:'Boubacar Koné',phone:'+223 66 38 72 10',district:'Kalaban Coura',product:'Nocturne Chrono',reference:'T-01',color:'Noir & brun',finish:'Acier noir',size:'44 mm',quantity:2,unit:52000,total:104000}
];
function renderOrderInspector(configuration){return '<section class="panel order-inspector"><div class="panel-head"><div><p class="kicker">Détail de la commande</p><h2>'+configuration.product+'</h2></div><span class="chip">'+configuration.id+'</span></div><div class="costs"><span>Client<b>'+configuration.customer+'</b></span><span>Téléphone<b>'+configuration.phone+'</b></span><span>Quartier<b>'+configuration.district+'</b></span><span>Référence<b>'+configuration.reference+'</b></span><span>Coloris<b>'+configuration.color+'</b></span><span>Finition<b>'+configuration.finish+'</b></span><span>Diamètre<b>'+configuration.size+'</b></span><span>Quantité<b>'+configuration.quantity+'</b></span><span>Prix unitaire<b>'+money(configuration.unit)+'</b></span><span>Sous-total<b>'+money(configuration.total)+'</b></span></div><p style="margin:16px 0 0;color:#756f66;font-size:12px">Livraison offerte · Paiement à la réception</p></section>'}
function addOrderInspector(){if(page!=='orders'||app.querySelector('.order-inspector'))return;const rows=[...app.querySelectorAll('.table-row:not(.head-row)')],panel=document.createElement('div');panel.innerHTML=renderOrderInspector(orderConfigurations[0]);app.append(panel.firstElementChild);rows.forEach((row,index)=>{row.style.cursor='pointer';row.title='Afficher le détail complet';row.onclick=()=>{const inspector=app.querySelector('.order-inspector');inspector.outerHTML=renderOrderInspector(orderConfigurations[index])}})}
new MutationObserver(addOrderInspector).observe(app,{childList:true,subtree:true});addOrderInspector();
`;

await mkdir(reviewDirectory, { recursive: true });
await Promise.all([
  writeFile(resolve(reviewDirectory, "TUMA-revue-boutique.html"), documentShell({ title: "TUMA — Revue boutique", styles: storeStyles + storeExtraStyles, body: storeBody, script: storeScript }), "utf8"),
  writeFile(resolve(reviewDirectory, "TUMA-revue-admin.html"), documentShell({ title: "TUMA — Revue administration", styles: adminStyles, body: adminBody, script: adminScript + adminOrderDetailsScript }), "utf8"),
]);

console.log("Fichiers de revue générés dans review/");
